+    private void checkAndMaintainIntegrity(RuleViolationFileNameStrategy strategy) {
+        IntegritySnapshot snapshot = inspect(strategy);
+        if (integrityMode == IntegrityMode.FAIL) {
+            if (!snapshot.problems().isEmpty()) {
+                throw new StoreInitializationFailedException(snapshot.report());
+            }
+            return;
+        }
+
+        boolean changed = false;
+        for (EntryInfo entry : snapshot.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteResolvedEntryFile(entry);
+                storedRules.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveMisplacedEntry(entry);
+                storedRules.put(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            storedRules.sync();
+        }
+    }
