+    private IntegritySnapshot inspect(RuleViolationFileNameStrategy strategy) {
+        List<EntryInfo> entries = new ArrayList<>();
+        for (Map.Entry<String, String> property : storedRules.entries()) {
+            String description = property.getKey();
+            String fileName = property.getValue();
+            String derivedName = deriveFileName(strategy, description, true);
+            entries.add(new EntryInfo(description, fileName, derivedName, pathFor(fileName), pathFor(derivedName)));
+        }
+
+        Map<String, Integer> recordedNameCounts = counts(entries, entry -> entry.fileName);
+        Map<String, Integer> derivedNameCounts = counts(entries, entry -> entry.derivedName);
+        Map<String, Integer> resolvedPathCounts = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            String resolvedKey = existingRegularFileKey(entry.namedPath);
+            if (resolvedKey != null) {
+                resolvedPathCounts.put(resolvedKey, resolvedPathCounts.getOrDefault(resolvedKey, 0) + 1);
+            }
+        }
+
+        for (EntryInfo entry : entries) {
+            entry.broken = !isResolvedFileDirectlyInFolder(entry.namedPath);
+            if (!entry.broken) {
+                entry.resolvedPath = realPath(entry.namedPath);
+                entry.resolved = containsNoViolations(entry.resolvedPath);
+            }
+            String resolvedKey = existingRegularFileKey(entry.namedPath);
