+    private Map<String, Integer> counts(List<EntryInfo> entries, NameExtractor extractor) {
+        Map<String, Integer> result = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            String name = extractor.get(entry);
+            result.put(name, result.getOrDefault(name, 0) + 1);
+        }
+        return result;
+    }
+
+    private List<String> directUnownedFiles(List<EntryInfo> entries) {
+        Set<String> recordedNames = new HashSet<>();
+        for (EntryInfo entry : entries) {
+            recordedNames.add(entry.fileName);
+        }
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
+            for (Path file : files) {
+                if (!file.getFileName().toString().equals(STORED_RULES_FILE_NAME)
