+            }
+            return path.toRealPath().toString();
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private boolean isResolvedFileDirectlyInFolder(Path path) {
+        try {
+            Path resolved = path.toRealPath();
+            return resolved.getParent().equals(storeFolderPath) && Files.isRegularFile(resolved, java.nio.file.LinkOption.NOFOLLOW_LINKS);
+        } catch (IOException e) {
