+        }
+    }
+
+    private Path realPath(Path path) {
+        try {
+            return path.toRealPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean containsNoViolations(Path path) {
+        try {
+            byte[] bytes = Files.readAllBytes(path);
+            String text = new String(bytes, UTF_8);
+            return text.isEmpty() || ONLY_LINE_BREAKS_PATTERN.matcher(text).matches();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean pathExists(Path path) {
+        return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
+                || Files.isSymbolicLink(path);
+    }
+
+    private boolean escapesFolder(Path path) {
+        Path normalized = path.toAbsolutePath().normalize();
+        if (!normalized.getParent().equals(storeFolderPath)) {
+            return true;
+        }
+        try {
