+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void deleteResolvedEntryFile(EntryInfo entry) {
+        try {
+            Files.deleteIfExists(entry.resolvedPath);
+            if (!entry.namedPath.equals(entry.resolvedPath)) {
+                Files.deleteIfExists(entry.namedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
