+    private void checkSafeSavePath(String fileName, Path ruleFile, String owningDescription) {
+        if (!isSafeStorePath(ruleFile) || resolvesToIndex(ruleFile) || fileName.equals(STORED_RULES_FILE_NAME)) {
+            throw new StoreUpdateFailedException(String.format("Violation file '%s' is outside the store or is the store index", fileName));
+        }
+        if (pathExists(ruleFile) && owningDescription == null) {
+            throw new StoreUpdateFailedException(String.format("Violation file '%s' is already occupied", fileName));
+        }
+    }
+
+    private boolean isSafeStorePath(Path path) {
+        return path.toAbsolutePath().normalize().getParent().equals(storeFolderPath)
+                && !escapesFolder(path);
+    }
+
+    private boolean resolvesToIndex(Path path) {
+        try {
+            return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
+                    && path.toRealPath().equals(storedRulesPath.toRealPath());
+        } catch (IOException e) {
+            return true;
+        }
