+    private void write(List<String> violations, Path ruleDetails, boolean newEntry) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
+            Files.write(temporary, builder.toString().getBytes(UTF_8), StandardOpenOption.TRUNCATE_EXISTING);
+            if (newEntry) {
+                Files.move(temporary, ruleDetails, StandardCopyOption.ATOMIC_MOVE);
+            } else {
+                moveReplacingAtomically(temporary, ruleDetails);
+            }
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                try {
+                    Files.deleteIfExists(temporary);
+                } catch (IOException ignored) {
+                    log.debug("Could not remove temporary violation file {}", temporary, ignored);
+                }
+            }
+        }
+    }
