    private IntegritySnapshot inspect(RuleViolationFileNameStrategy strategy) {
        List<EntryInfo> entries = new ArrayList<>();
        for (Map.Entry<String, String> property : storedRules.entries()) {
            String description = property.getKey();
            String fileName = property.getValue();
            String derivedName = randomFileNames ? fileName : deriveFileName(strategy, description, true);
            entries.add(new EntryInfo(description, fileName, derivedName, pathFor(fileName), pathFor(derivedName)));
        }

        Map<String, Integer> recordedNameCounts = counts(entries, entry -> entry.fileName);
        Map<String, Integer> derivedNameCounts = counts(entries, entry -> entry.derivedName);
        Map<String, Integer> resolvedPathCounts = new HashMap<>();
        for (EntryInfo entry : entries) {
            String resolvedKey = existingRegularFileKey(entry.namedPath);
            if (resolvedKey != null) {
                resolvedPathCounts.put(resolvedKey, resolvedPathCounts.getOrDefault(resolvedKey, 0) + 1);
            }
        }

        for (EntryInfo entry : entries) {
            entry.broken = !isResolvedFileDirectlyInFolder(entry.namedPath);
            if (!entry.broken) {
                entry.resolvedPath = realPath(entry.namedPath);
                entry.resolved = containsNoViolations(entry.resolvedPath);
            }
            String resolvedKey = existingRegularFileKey(entry.namedPath);
            entry.shared = recordedNameCounts.get(entry.fileName) > 1
                    || (resolvedKey != null && resolvedPathCounts.get(resolvedKey) > 1);
            entry.misplaced = !entry.fileName.equals(entry.derivedName);
            entry.colliding = derivedNameCounts.get(entry.derivedName) > 1;
            entry.occupied = entry.misplaced && (pathExists(entry.derivedPath)
                    || recordedNameCounts.getOrDefault(entry.derivedName, 0) > 0
                    || escapesFolder(entry.derivedPath));
        }

        List<String> unownedFiles = directUnownedFiles(entries);
        return new IntegritySnapshot(entries, unownedFiles);
    }

    private Map<String, Integer> counts(List<EntryInfo> entries, NameExtractor extractor) {
        Map<String, Integer> result = new HashMap<>();
        for (EntryInfo entry : entries) {
            String name = extractor.get(entry);
            result.put(name, result.getOrDefault(name, 0) + 1);
        }
        return result;
    }

    private List<String> directUnownedFiles(List<EntryInfo> entries) {
        Set<String> recordedNames = new HashSet<>();
        Set<String> recordedFiles = new HashSet<>();
        for (EntryInfo entry : entries) {
            recordedNames.add(entry.fileName);
            String resolvedFile = existingRegularFileKey(entry.namedPath);
            if (resolvedFile != null) {
                recordedFiles.add(resolvedFile);
            }
        }
        List<String> result = new ArrayList<>();
        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
            for (Path file : files) {
                if (!file.getFileName().toString().equals(STORED_RULES_FILE_NAME)
                        && Files.isRegularFile(file, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                        && !recordedNames.contains(file.getFileName().toString())
                        && !recordedFiles.contains(file.toRealPath().toString())) {
                    result.add(file.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        Collections.sort(result);
        return result;
    }

    private String existingRegularFileKey(Path path) {
        try {
            if (!Files.isRegularFile(path)) {
                return null;
            }
            return path.toRealPath().toString();
        } catch (IOException e) {
            return null;
        }
    }

    private boolean isResolvedFileDirectlyInFolder(Path path) {
        if (path.toAbsolutePath().normalize().equals(storedRulesPath)) {
            return false;
        }
        try {
            Path resolved = path.toRealPath();
            return !resolved.equals(storedRulesPath)
                    && resolved.getParent().equals(storeFolderPath)
                    && Files.isRegularFile(resolved, java.nio.file.LinkOption.NOFOLLOW_LINKS);
        } catch (IOException e) {
            return false;
        }
    }

    private Path realPath(Path path) {
        try {
            return path.toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean containsNoViolations(Path path) {
        try {
            byte[] bytes = Files.readAllBytes(path);
            String text = new String(bytes, UTF_8);
            return text.isEmpty() || ONLY_LINE_BREAKS_PATTERN.matcher(text).matches();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean pathExists(Path path) {
        return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                || Files.isSymbolicLink(path);
    }

    private boolean escapesFolder(Path path) {
        Path normalized = path.toAbsolutePath().normalize();
        if (!normalized.getParent().equals(storeFolderPath)) {
            return true;
        }
        try {
            return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                    && !path.toRealPath().getParent().equals(storeFolderPath);
        } catch (IOException e) {
            return true;
        }
    }

    private void moveMisplacedEntry(EntryInfo entry) {
        if (!isSafeStorePath(entry.derivedPath) || pathExists(entry.derivedPath)) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot move misplaced violation file for rule '%s' to %s", entry.description, entry.derivedName));
        }
        try {
            // A symlink is a name for a file here; move its target, leaving no link that
            // would make the newly repaired index point at the wrong object.
            Files.move(entry.resolvedPath, entry.derivedPath);
            if (Files.isSymbolicLink(entry.namedPath)) {
                Files.delete(entry.namedPath);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void deleteResolvedEntryFile(EntryInfo entry) {
        try {
            Files.deleteIfExists(entry.resolvedPath);
            if (!entry.namedPath.equals(entry.resolvedPath)) {
                Files.deleteIfExists(entry.namedPath);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeLock) {
            reloadStoredRules();
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        synchronized (storeLock) {
            reloadStoredRules();
            if (!storeUpdateAllowed) {
                throw new StoreUpdateFailedException(String.format(
                        "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
            }
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                if (existingFileName == null) {
                    return;
                }
                forgetRule(description, existingFileName);
                return;
            }

            boolean newEntry = existingFileName == null;
            String ruleFileName = newEntry
                    ? deriveFileName(activeStrategy, description, false)
                    : existingFileName;
            Path ruleFile = pathFor(ruleFileName);
            checkSafeSavePath(ruleFileName, ruleFile, newEntry ? null : description);
            if (newEntry && pathExists(ruleFile)) {
                throw new StoreUpdateFailedException(String.format("Violation file '%s' is already occupied", ruleFileName));
            }

            Path writePath = newEntry ? ruleFile : targetForWrite(ruleFile);
            write(violations, writePath, newEntry);
            if (newEntry) {
                try {
                    storedRules.put(description, ruleFileName);
                    storedRules.sync();
                } catch (RuntimeException e) {
                    try {
                        Files.deleteIfExists(ruleFile);
                    } catch (IOException cleanupFailure) {
                        e.addSuppressed(cleanupFailure);
                    }
                    throw e;
                }
            }
        }
    }

    private RuleViolationFileNameStrategy activeStrategy;

    private void reloadStoredRules() {
        storedRules.reload();
    }

    private void checkSafeSavePath(String fileName, Path ruleFile, String owningDescription) {
        if (!isSafeStorePath(ruleFile) || resolvesToIndex(ruleFile) || fileName.equals(STORED_RULES_FILE_NAME)) {
            throw new StoreUpdateFailedException(String.format("Violation file '%s' is outside the store or is the store index", fileName));
        }
        if (pathExists(ruleFile) && owningDescription == null) {
            throw new StoreUpdateFailedException(String.format("Violation file '%s' is already occupied", fileName));
        }
    }

    private Path targetForWrite(Path ruleFile) {
        if (!Files.isSymbolicLink(ruleFile)) {
            return ruleFile;
        }
        try {
            Path target = ruleFile.toRealPath();
            if (!target.getParent().equals(storeFolderPath) || target.equals(storedRulesPath)) {
                throw new IOException("Violation file target is outside the store");
            }
            return target;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private boolean isSafeStorePath(Path path) {
        return path.toAbsolutePath().normalize().getParent().equals(storeFolderPath)
                && !escapesFolder(path);
    }

    private boolean resolvesToIndex(Path path) {
        try {
            return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                    && path.toRealPath().equals(storedRulesPath.toRealPath());
        } catch (IOException e) {
            return true;
        }
    }

    private void write(List<String> violations, Path ruleDetails, boolean newEntry) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        Path temporary = null;
        try {
            temporary = Files.createTempFile(storeFolderPath, ".violation-", ".tmp");
            Files.write(temporary, builder.toString().getBytes(UTF_8), StandardOpenOption.TRUNCATE_EXISTING);
            if (newEntry) {
                try {
                    Files.move(temporary, ruleDetails, StandardCopyOption.ATOMIC_MOVE);
                } catch (java.nio.file.AtomicMoveNotSupportedException e) {
                    Files.move(temporary, ruleDetails);
                }
            } else {
                moveReplacingAtomically(temporary, ruleDetails);
            }
            temporary = null;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        } finally {
            if (temporary != null) {
                try {
                    Files.deleteIfExists(temporary);
                } catch (IOException ignored) {
                    log.debug("Could not remove temporary violation file {}", temporary, ignored);
                }
            }
        }
        }
    }

    private void moveReplacingAtomically(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (java.nio.file.AtomicMoveNotSupportedException e) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void forgetRule(String description, String fileName) {
        List<EntryInfo> entries = new ArrayList<>();
        for (Map.Entry<String, String> property : storedRules.entries()) {
            if (!property.getKey().equals(description)) {
                entries.add(new EntryInfo(property.getKey(), property.getValue(), null, pathFor(property.getValue()), null));
            }
        }
        boolean shared = false;
        Path file = pathFor(fileName);
        String realFile = existingRegularFileKey(file);
        for (EntryInfo entry : entries) {
            if (entry.fileName.equals(fileName)
                    || (realFile != null && realFile.equals(existingRegularFileKey(entry.namedPath)))) {
                shared = true;
                break;
            }
        }
        if (!shared && pathExists(file)) {
            if (!isSafeStorePath(file) || resolvesToIndex(file)) {
                throw new StoreUpdateFailedException(String.format("Cannot remove violation file '%s'", fileName));
            }
            try {
                boolean symbolicLink = Files.isSymbolicLink(file);
                Path target = symbolicLink ? file.toRealPath() : file;
                // The target is part of the stored file represented by the entry;
                // remove it as well, but only after the target has been verified to
                // remain inside this store.
                if (symbolicLink) {
                    if (!target.getParent().equals(storeFolderPath)) {
                        throw new IOException("Violation file target is outside the store");
                    }
                    Files.deleteIfExists(target);
                }
                Files.delete(file);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
        storedRules.remove(description);
        storedRules.sync();
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storeLock) {
            reloadStoredRules();
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(ruleDetailsFileName);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(String ruleDetailsFileName) {
        String violationsText = readStoreFile(ruleDetailsFileName);
        if (violationsText.isEmpty() || ONLY_LINE_BREAKS_PATTERN.matcher(violationsText).matches()) {
            return Collections.emptyList();
        }
        return SplitterHelper.split(violationsText).stream().map(this::unescape).collect(toList());
    }

    private String readStoreFile(String fileName) {
        try {
            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
            return ensureUnixLineBreaks(result);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private Path pathFor(String fileName) {
        return storeFolderPath.resolve(fileName);
    }

    private String deriveFileName(RuleViolationFileNameStrategy strategy, String description, boolean initialization) {
        String result;
        try {
            result = strategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw initialization ? new StoreInitializationFailedException(e) : new StoreUpdateFailedException(e);
        }
        if (result == null || result.trim().isEmpty()) {
            String message = String.format("RuleViolationFileNameStrategy returned no file name for rule '%s'", description);
            throw initialization ? new StoreInitializationFailedException(message) : new StoreUpdateFailedException(message);
        }
        return result;
    }

    private String reportEntry(EntryInfo entry) {
        return "  " + entry.description + " -> " + entry.fileName;
    }

    private interface NameExtractor {
        String get(EntryInfo entry);
    }

    private enum IntegrityMode {
        IGNORE, REPAIR, FAIL;

        static IntegrityMode from(String value) {
            if ("ignore".equals(value)) {
                return IGNORE;
            }
            if ("repair".equals(value)) {
                return REPAIR;
            }
            if ("fail".equals(value)) {
                return FAIL;
            }
            throw new StoreInitializationFailedException(String.format(
                    "Invalid %s='%s'; accepted values are repair, fail and ignore", INTEGRITY_PROPERTY_NAME, value));
        }
    }

    private class IntegritySnapshot {
        private final List<EntryInfo> entries;
        private final List<String> unownedFiles;

        IntegritySnapshot(List<EntryInfo> entries, List<String> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        List<String> problems() {
            List<String> result = new ArrayList<>();
            for (EntryInfo entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    result.add(reportEntry(entry));
                }
            }
            result.addAll(unownedFiles);
            return result;
        }

        String report() {
            StringBuilder result = new StringBuilder("Violation store integrity check failed");
            appendEntries(result, "Broken entries", entry -> entry.broken);
            appendEntries(result, "Resolved entries", entry -> entry.resolved);
            appendEntries(result, "Shared entries", entry -> entry.shared);
            if (!unownedFiles.isEmpty()) {
                result.append("\nUnowned files");
                for (String file : unownedFiles) {
                    result.append("\n  ").append(file);
                }
            }
            appendEntries(result, "Misplaced entries", entry -> entry.misplaced);
            appendEntries(result, "Colliding entries", entry -> entry.colliding);
            appendEntries(result, "Occupied entries", entry -> entry.occupied);
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String heading, EntryPredicate predicate) {
            List<EntryInfo> matching = entries.stream().filter(predicate::matches)
                    .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
            if (!matching.isEmpty()) {
